create table public.capturas(id uuid primary key default gen_random_uuid(),usuario_id uuid not null default auth.uid() references public.perfiles(id) on delete cascade,especie_id uuid references public.especies(id) on delete set null,especie_texto text,fecha timestamptz not null default now(),peso_kg numeric check(peso_kg>=0),longitud_cm numeric check(longitud_cm>=0),lugar text,notas text,foto_path text);
create table public.notas(id uuid primary key default gen_random_uuid(),usuario_id uuid not null default auth.uid() references public.perfiles(id) on delete cascade,titulo text not null,contenido text not null,creado_en timestamptz not null default now());
create table public.favoritos_consejos(usuario_id uuid not null default auth.uid() references public.perfiles(id) on delete cascade,consejo_id uuid references public.consejos(id) on delete cascade,creado_en timestamptz not null default now(),primary key(usuario_id,consejo_id));
create table public.reportes(id uuid primary key default gen_random_uuid(),usuario_id uuid not null default auth.uid() references public.perfiles(id) on delete cascade,titulo text not null,descripcion text not null,estado text not null default 'pendiente' check(estado in ('pendiente','en_revision','resuelto')),respuesta text,creado_en timestamptz not null default now());
alter table public.capturas enable row level security; revoke all on public.capturas from anon,authenticated; grant select,insert,update,delete on public.capturas to authenticated; create policy propios on public.capturas for all to authenticated using(usuario_id=(select auth.uid()) and (select privado.activo())) with check(usuario_id=(select auth.uid()) and (select privado.activo()));
alter table public.notas enable row level security; revoke all on public.notas from anon,authenticated; grant select,insert,update,delete on public.notas to authenticated; create policy propios on public.notas for all to authenticated using(usuario_id=(select auth.uid()) and (select privado.activo())) with check(usuario_id=(select auth.uid()) and (select privado.activo()));
alter table public.favoritos_consejos enable row level security; revoke all on public.favoritos_consejos from anon,authenticated; grant select,insert,update,delete on public.favoritos_consejos to authenticated; create policy propios on public.favoritos_consejos for all to authenticated using(usuario_id=(select auth.uid()) and (select privado.activo())) with check(usuario_id=(select auth.uid()) and (select privado.activo()) and exists(select 1 from public.consejos c where c.id=consejo_id));
alter table public.reportes enable row level security;
revoke all on public.reportes from anon,authenticated;
grant select on public.reportes to authenticated;
grant insert(titulo,descripcion,usuario_id) on public.reportes to authenticated;
grant update(estado,respuesta) on public.reportes to authenticated;
create policy reportes_lectura on public.reportes for select to authenticated using ((usuario_id=(select auth.uid()) and (select privado.activo())) or (select privado.es_admin()));
create policy reportes_crear on public.reportes for insert to authenticated with check(usuario_id=(select auth.uid()) and (select privado.activo()));
create policy reportes_responder on public.reportes for update to authenticated using((select privado.es_admin())) with check((select privado.es_admin()));
create index capturas_usuario_idx on public.capturas(usuario_id);
create index capturas_especie_idx on public.capturas(especie_id);
create index notas_usuario_idx on public.notas(usuario_id);
create index favoritos_consejo_idx on public.favoritos_consejos(consejo_id);
create index reportes_usuario_idx on public.reportes(usuario_id);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('catalogo','catalogo',false,5242880,array['image/jpeg','image/png','image/webp']),('personal','personal',false,5242880,array['image/jpeg','image/png','image/webp']);
create policy catalogo_lectura on storage.objects for select to authenticated using(bucket_id='catalogo' and ((select privado.activo()) or (select privado.es_admin())));
create policy catalogo_admin on storage.objects for all to authenticated using(bucket_id='catalogo' and (select privado.es_admin())) with check(bucket_id='catalogo' and (select privado.es_admin()));
create policy personal_propio on storage.objects for all to authenticated using(bucket_id='personal' and (storage.foldername(name))[1]=(select auth.uid())::text and (select privado.activo())) with check(bucket_id='personal' and (storage.foldername(name))[1]=(select auth.uid())::text and (select privado.activo()));
;
